WITH flagged AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) > INTERVAL '14' DAY THEN 1 ELSE 0 END AS new_group_flag FROM payments), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT DATE_TRUNC('WEEK', paid_at) AS week_start, CASE WHEN new_group_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END AS new_group_flag_tier, order_id, COUNT(*) AS row_count, MAX(paid_at) AS last_paid_at, SIZE(COLLECT_SET(method)) AS num_methods FROM islands GROUP BY GROUPING SETS ((DATE_TRUNC('WEEK', paid_at), CASE WHEN new_group_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END, order_id), (DATE_TRUNC('WEEK', paid_at), CASE WHEN new_group_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END), ()) ORDER BY order_id NULLS FIRST
